// A schema builder that keeps its bookkeeping keys out of enumeration:
// every schema is a plain object whose `~kind` (and `~optional`) are
// non-enumerable data properties, so JSON.stringify of a schema is the
// JSON Schema document and nothing else.
function withHidden(target, hidden) {
  for (const key of Object.keys(hidden)) {
    Object.defineProperty(target, key, {
      configurable: true,
      writable: true,
      enumerable: false,
      value: hidden[key],
    });
  }
  return target;
}

function create(hidden, visible, options = {}) {
  return withHidden({ ...visible, ...options }, hidden);
}

// A copy that keeps each key's enumerability, descriptor by descriptor.
function clone(schema) {
  const result = {};
  for (const key of Object.getOwnPropertyNames(schema)) {
    const descriptor = Object.getOwnPropertyDescriptor(schema, key);
    if (descriptor.enumerable === true) result[key] = descriptor.value;
    else Object.defineProperty(result, key, descriptor);
  }
  return result;
}

export function text(options) {
  return create({ "~kind": "Text" }, { type: "string" }, options);
}

export function count(options) {
  return create({ "~kind": "Count" }, { type: "integer" }, options);
}

export function optional(schema) {
  return withHidden(clone(schema), { "~optional": true });
}

export function list(items, options) {
  return create({ "~kind": "List" }, { type: "array", items }, options);
}

export function shape(properties, options) {
  const required = Object.keys(properties).filter((key) => properties[key]["~optional"] !== true);
  return create({ "~kind": "Shape" }, { type: "object", required, properties }, options);
}

export function kindOf(schema) {
  return typeof schema === "object" && schema !== null ? schema["~kind"] : undefined;
}

export function isKind(schema, kind) {
  return kindOf(schema) === kind;
}

export function describe(schema) {
  const hidden = Object.getOwnPropertyNames(schema).filter(
    (key) => !Object.prototype.propertyIsEnumerable.call(schema, key),
  );
  return `${kindOf(schema)} visible=${Object.keys(schema).join(",")} hidden=${hidden.join(",")}`;
}

export function check(schema, value) {
  switch (kindOf(schema)) {
    case "Text":
      return typeof value === "string";
    case "Count":
      return typeof value === "number" && value % 1 === 0;
    case "List":
      return Array.isArray(value) && value.every((item) => check(schema.items, item));
    case "Shape": {
      if (typeof value !== "object" || value === null) return false;
      for (const key of Object.keys(schema.properties)) {
        const property = schema.properties[key];
        if (!(key in value)) {
          if (property["~optional"] !== true) return false;
        } else if (!check(property, value[key])) return false;
      }
      return true;
    }
    default:
      return false;
  }
}
